import { findByEmail, isActive, findUserForLogin } from '../src/services/auth-service.js';
import { UserRepository } from '../src/repositories/user-repository.js';

test('findUserForLogin returns the live user with that email', async () => {
  const user = await findUserForLogin('ada@example.com');
  assert.equal(user.id, 1);
});

test('findUserForLogin returns null for a soft-deleted or unknown email', async () => {
  assert.equal(await findUserForLogin('alan@example.com'), null);
  assert.equal(await findUserForLogin('nobody@example.com'), null);
});

test('findUserForLogin rejects with repository errors', async (t) => {
  const boom = new Error('boom');
  t.mock.method(UserRepository.prototype, 'findByEmail', () => Promise.reject(boom));
  await assert.rejects(findUserForLogin('ada@example.com'), boom);
});

